// Replicates the frontend AES-CBC password encryption (passwordEncrypt.js)
// so a bearer token can be obtained without a browser.
import crypto from 'node:crypto';

const KEY = Buffer.from('A-16-Byte-keyValA-16-Byte-keyVal', 'utf8');
const IV = Buffer.from('A-16-Byte-String', 'utf8');

export function encryptPassword(plain) {
  const cipher = crypto.createCipheriv('aes-256-cbc', KEY, IV);
  return Buffer.concat([cipher.update(String(plain), 'utf8'), cipher.final()]).toString('base64');
}

if (process.argv[2]) console.log(encryptPassword(process.argv[2]));

// Compute the login password ciphertext with the SAME crypto-js the page loads,
// so the result is byte-identical to what the browser sends.
import { readFileSync } from 'node:fs';
import vm from 'node:vm';

const LIB = 'D:/repository/苏州市房地产监测V3/zhi2-web-admin/public/assets/js/crypto-js.min.js';
const sandbox = { window: {}, self: {}, console };
sandbox.window = sandbox;
vm.createContext(sandbox);
vm.runInContext(readFileSync(LIB, 'utf8'), sandbox);

const CryptoJS = sandbox.CryptoJS || sandbox.window.CryptoJS;
if (!CryptoJS) throw new Error('CryptoJS not found in bundle');

const key = CryptoJS.enc.Utf8.parse('A-16-Byte-keyValA-16-Byte-keyVal');
const iv = CryptoJS.enc.Utf8.parse('A-16-Byte-String');
const out = CryptoJS.AES.encrypt(CryptoJS.enc.Utf8.parse(String(process.argv[2])), key, {
  iv,
  mode: CryptoJS.mode.CBC,
  padding: CryptoJS.pad.Pkcs7
}).toString();
console.log(out);

// Renders the price-filing flow records with the OLD and NEW maps using real
// values observed in the dev database (ACT_HI_COMMENT.TYPE_ = 1 / 3 / 9).
// Confirms the fix produces the unified component's wording and colours.

const OLD_statusShow = { 0: '通过', 1: '退回', 3: '已阅', undefined: '待审批' };
const OLD_note = '旧的 className 直接用 statusShow[...] 取值，没有 green/red 类';

const NEW_statusMap = { 1: '通过', 2: '退回', 3: '驳回', 4: '委派', 5: '转办', 6: '终止', 9: '驳回至起点', undefined: '待审批' };
const NEW_colorMap = { 1: 'green', 2: 'red', 3: 'red', 4: 'yellow', 5: 'yellow', 6: 'black', 9: 'red', undefined: 'yellow' };

const rows = [
  { TIME_: '2025-11-18 11:58:46', MSG: 'system发起流程申请', TYPE_: 1 },
  { TIME_: '2025-11-18 13:35:03', MSG: '驳回', TYPE_: 3 },
